993	// pointStats 是区间统计（query）与固定窗口统计（query_windows）共用的
994	// 点数与均值累计器：逐点累计个数与精确有理数总和。写入侧已保证值有限，
995	// SetFloat64 对有限值是精确的，因此求和与点的提交顺序、批次划分无关，
996	// 正负大数抵消后的微小余量不会丢失，总和超出 float64 有限范围时均值仍有限。
997	// 两种统计只在“哪些点归入哪一组”上不同，点数与均值规则统一由这里维护：
998	// 区间统计为整条序列使用一个累计器，固定窗口统计为每个实际有点的窗口各建
999	// 一个独立累计器，窗口之间天然互不携带点数与数值，不需要在窗口间清空复用。
1000	type pointStats struct {
1001		count int
1002		sum   *big.Rat
1003		tmp   *big.Rat
1004	}
1005	
1006	func newPointStats() *pointStats {
1007		return &pointStats{sum: new(big.Rat), tmp: new(big.Rat)}
1008	}
1009	
1010	// add 把一个实际保存的 float64 采样值计入统计。
1011	func (a *pointStats) add(v float64) {
1012		a.count++
1013		a.sum.Add(a.sum, a.tmp.SetFloat64(v))
1014	}
1015	
1016	// average 返回精确算术平均舍入到最近可表示 float64 的结果（正中取偶；
1017	// 精确为零时返回 +0）。调用方保证至少 add 过一次。不改动累计状态。
1018	func (a *pointStats) average() float64 {
1019		return ratToFloat64NearestEven(new(big.Rat).Quo(a.sum, a.tmp.SetInt64(int64(a.count))))
1020	}
1021	
1022	// runQuery 只读统计已成功提交的数据：name 精确、标签子集、[start,end] 闭区间。
1023	// 序列身份的整理（标签副本、排序键值对、排列次序）与写入快照共用同一套
1024	// organizeSeries 规则，只是入选范围不同：这里先按名称与标签条件筛出命中序列
1025	// 再整理，不为无关指标承担展示准备；筛后剩余序列的相对次序因此与写入全量
1026	// 结果一致。查询只返回每条序列的点数与均值，不构造采样明细列表（明细由
1027	// query_points 操作提供）——单次遍历点表直接累计进 pointStats（计数与
1028	// 均值都与点的排列次序无关）。区间内没有点的序列不列出，不补零值条目。
1029	func (s *MetricStore) runQuery(q parsedQuery) *QueryResult {
1030		organized := organizeSeries(s.matchSeries(q))
1031	
1032		out := make([]QuerySeries, 0, len(organized))
1033		for _, entry := range organized {
1034			// 一次遍历直接统计：不构造值切片、不排序时间戳，避免为只返回
1035			// count/average 的查询承担采样明细展示。点数与均值的累计和舍入
1036			// 规则与固定窗口统计共用 pointStats。
1037			stats := newPointStats()
1038			for ts, v := range entry.sr.points {
1039				if ts < q.start || ts > q.end {
1040					continue
1041				}
1042				stats.add(v)
1043			}
1044			if stats.count == 0 {
1045				continue
1046			}
1047			out = append(out, QuerySeries{
1048				Name:    entry.ref.Name,
1049				Labels:  entry.ref.Labels,
1050				Count:   stats.count,
1051				Average: stats.average(),
1052			})
1053		}
1054		return &QueryResult{Status: "ok", Op: "query", Series: out}
1055	}
1056	
1057	// runQueryPoints 只读列出已成功提交的采样明细：name 精确、标签子集、
1058	// [start,end] 闭区间，与 runQuery 共用同一套序列筛选与 organizeSeries 整理
1059	// 规则，因此序列排列次序与均值查询一致。每条命中序列保留完整指标名与完整
1060	// 标签集合，points 按时间戳升序列出区间内的 timestamp 与 value，不附加
1061	// count 或 average；区间内没有点的序列不列出，没有任何命中时 series 为
1062	// 空数组。时间戳以 int64 比较与输出，保留整数精度；value 是实际存储的
1063	// float64。查询只读，不改变采样值或写入计数。
1064	func (s *MetricStore) runQueryPoints(q parsedQuery) *QueryPointsResult {
1065		organized := organizeSeries(s.matchSeries(q))
1066	
1067		out := make([]QueryPointsSeries, 0, len(organized))
1068		for _, entry := range organized {
1069			points := seriesPointsInRange(entry.sr, q.start, q.end)
1070			if len(points) == 0 {
1071				continue
1072			}
1073			out = append(out, QueryPointsSeries{
1074				Name:   entry.ref.Name,
1075				Labels: entry.ref.Labels,
1076				Points: points,
1077			})
1078		}
1079		return &QueryPointsResult{Status: "ok", Op: "query_points", Series: out}
1080	}
1081	
1082	// seriesPointsInRange 按 timestamp 升序返回一条已存序列在 [start,end] 闭区间
1083	// 内的采样点，供采样明细查询展示。选取、升序排列与点构造与写入快照共用
1084	// seriesPoints，区别只在传入的选取范围是闭区间而不是全部。
1085	func seriesPointsInRange(sr *storedSeries, start, end int64) []Point {
1086		return seriesPoints(sr, func(ts int64) bool { return ts >= start && ts <= end })
1087	}
1088	
1089	// runQueryWindows 只读统计固定时间窗口内的点数与均值：窗口把 [start,end]
1090	// 闭区间按 step 毫秒从 start 起连续划分，第 k 个窗口为
1091	// [start+k*step, start+(k+1)*step-1]（含首尾毫秒），最后一个截到 end，
1092	// 各序列共用同一组由 start 与 step 决定的边界——即使区间横跨整个 int64 也不
1093	// 预先物化窗口表，临时数据只围绕实际有点的窗口组织。
1094	//
1095	// 名称精确、标签子集的序列筛选与 organizeSeries 整理、序列排列次序和另两种
1096	// 查询完全一致。每条序列独立统计：窗口统计不依赖采样明细展示——既不为统计
1097	// 构造区间内的完整采样点切片，也不对全部区间时间戳排序；直接遍历点表，按
1098	// floor((ts-start)/step) 把每个点归入它唯一所属的窗口，只在某窗口第一次
1099	// 落有点时为它登记下标并建立独立的 pointStats（与区间统计共用同一套计数、
1100	// 精确求和与舍入规则）。大量点落入少数几个窗口时，累计器与窗口下标条目只
1101	// 有这几个窗口那么多；最后只对实际出现的窗口下标排序（稀疏采样跨越很长区间
1102	// 时其数量远小于区间内窗口总数），按窗口起点升序输出。空窗口不补零，整个
1103	// 区间没有点的序列不列出，无任何命中时 series 为空数组。每个点只计入所属
1104	// 窗口一次，与写入或遍历次序无关；start==end 时所有点归入唯一窗口。平均值
1105	// 依据实际存储的 float64 值计算，正负大数抵消或总和超出 float64 范围时仍得
1106	// 有限结果。查询只读，不改变存储。
1107	func (s *MetricStore) runQueryWindows(q parsedQuery) *QueryWindowsResult {
1108		organized := organizeSeries(s.matchSeries(q))
1109	
1110		// diff = end - start，可能达到 2^64-1（start 为 MinInt64、end 为 MaxInt64），
1111		// 只能以 uint64 承载；窗口下标与窗口内偏移都在这个无符号区间内运算。
1112		diff := uint64(q.end) - uint64(q.start)
1113	
1114		out := make([]QueryWindowsSeries, 0, len(organized))
1115		for _, entry := range organized {
1116			// 临时数据只围绕实际有点的窗口：stats 每个非空窗口一个独立累计器，
1117			// order 记录各窗口第一次落有点的次序；遍历点表前不构造任何窗口或明细。
1118			stats := make(map[uint64]*pointStats)
1119			order := make([]uint64, 0)
1120			for ts, v := range entry.sr.points {
1121				if ts < q.start || ts > q.end {
1122					continue
1123				}
1124				// 无符号偏移除以 step 得窗口下标；点表遍历次序任意，下标之间无序，
1125				// 因此以 map 归组而不依赖相邻点同属一个窗口。
1126				idx := (uint64(ts) - uint64(q.start)) / uint64(q.step)
1127				a := stats[idx]
1128				if a == nil {
1129					a = newPointStats()
1130					stats[idx] = a
1131					order = append(order, idx)
1132				}
1133				a.add(v)
1134			}
1135			if len(order) == 0 {
1136				continue
1137			}
1138			// 只为实际有点的窗口排序：稀疏采样跨越很长区间时，这里排序的下标数
1139			// 远小于区间内窗口总数，绝不触及空窗口。
1140			sort.Slice(order, func(i, j int) bool { return order[i] < order[j] })
1141			windows := make([]Window, 0, len(order))
1142			for _, idx := range order {
1143				windows = append(windows, buildWindow(q.start, q.end, q.step, diff, idx, stats[idx]))
1144			}
1145			out = append(out, QueryWindowsSeries{
1146				Name:    entry.ref.Name,
1147				Labels:  entry.ref.Labels,
1148				Windows: windows,
1149			})
1150		}
1151		return &QueryWindowsResult{Status: "ok", Op: "query_windows", Series: out}
1152	}
1153	
1154	// buildWindow 构造一个非空窗口的统计：窗口起点是 start + idx*step，终点是
1155	// 起点加 step 减一；起点加 step 减一越过查询区间（含无符号加法溢出）时截到
1156	// end。点数与均值取自该窗口独立累计的 stats，均值按与 query 相同的精确平均
1157	// 与居中取偶规则得出（精确为零返回 +0）。调用方保证 0 <= idx*step <= diff，
1158	// 且 stats 至少计入了一个点。
1159	func buildWindow(start, end, step int64, diff, idx uint64, stats *pointStats) Window {
1160		startOff := idx * uint64(step)
1161		wStart := int64AtOffset(start, startOff)
1162		wEnd := end
1163		// tail <= diff-startOff 的比较不做 startOff+tail 加法，避免无符号溢出
1164		// （step 接近 2^63 时朴素相加可能绕过 2^64）。
1165		if tail := uint64(step) - 1; tail <= diff-startOff {
1166			wEnd = int64AtOffset(start, startOff+tail)
1167		}
1168		return Window{
1169			Start:   wStart,
1170			End:     wEnd,
1171			Count:   stats.count,
1172			Average: stats.average(),
1173		}
1174	}
1175	
1176	// int64AtOffset 返回 start + off（0 <= off，且调用方保证结果不超过 MaxInt64）。
1177	// 直接做有符号相加在 start 接近 int64 下界、off 很大时会溢出，因此统一走
1178	// 无符号运算还原：start 非负时无符号相加必落在非负有符号范围；start 为负时
1179	// 以 -start 为界先回到非正区间、再跨入正区间，两个分支都不产生溢出。
1180	func int64AtOffset(start int64, off uint64) int64 {
1181		if start >= 0 {
1182			return int64(uint64(start) + off)
1183		}
1184		gap := uint64(-start) // 0 < gap <= 2^63（start 为 MinInt64 时恰为 2^63）
1185		if off <= gap {
1186			// gap-off 为 2^63 时 int64 表示恰为 MinInt64，取负仍是 MinInt64，语义正确。
1187			return -int64(gap - off)
1188		}
1189		return int64(off - gap)
1190	}
1191	
1192	// ratToFloat64NearestEven 把有理数 x 舍入到最近的 float64，半数取偶。
1193	// 调用方保证 |x| 不超过 MaxFloat64（有限值的均值必然满足），因此不会溢出。
1194	func ratToFloat64NearestEven(x *big.Rat) float64 {
1195		if x.Sign() == 0 {
1196			return 0
1197		}
1198		num := new(big.Int).Set(x.Num())
1199		den := x.Denom()
1200		neg := num.Sign() < 0
1201		if neg {
1202			num.Neg(num)
1203		}
1204	
1205		// e 满足 2^e <= num/den < 2^(e+1)。
1206		e := floorLog2Rat(num, den)
1207		var m *big.Int
1208		scale := 0
1209		if e >= -1022 {
1210			// 正规数：m 为 num/den 按 2^(e-52) 缩放后的 53 位舍入整数。
1211			scale = e - 52
1212			m = roundScaledRatio(num, den, scale)
1213			if m.BitLen() == 54 {
1214				// 舍入进位（如 1.111…1 进为 10.0），指数加一。
1215				m.Rsh(m, 1)
1216				scale++
1217			}
1218		} else {
1219			// 次正规数：有效位间距固定为 2^-1074；m 舍入为 0 时按 IEEE 得到带符号零。
1220			scale = -1074
1221			m = roundScaledRatio(num, den, scale)
1222		}
1223		// m < 2^53，可以精确放入 int64 与 float64。
1224		f := math.Ldexp(float64(m.Int64()), scale)
1225		if neg {
1226			return -f
1227		}
1228		return f
1229	}
1230	
1231	// floorLog2Rat 返回正有理数 num/den 的二进制阶：最大的 e 使 2^e <= num/den。
1232	func floorLog2Rat(num, den *big.Int) int {
1233		k := num.BitLen() - den.BitLen()
1234		var t big.Int
1235		if k >= 0 {
1236			t.Lsh(den, uint(k))
1237			if num.Cmp(&t) >= 0 {
1238				return k
1239			}
1240			return k - 1
1241		}
1242		t.Lsh(num, uint(-k))
1243		if t.Cmp(den) >= 0 {
1244			return k
1245		}
1246		return k - 1
1247	}
1248	
1249	// roundScaledRatio 返回 round(num / (den · 2^scale))，半数取偶；num、den 均为正。
1250	func roundScaledRatio(num, den *big.Int, scale int) *big.Int {
1251		n := new(big.Int).Set(num)
1252		d := new(big.Int).Set(den)
1253		if scale >= 0 {
1254			d.Lsh(d, uint(scale))
1255		} else {
1256			n.Lsh(n, uint(-scale))
1257		}
1258		q, r := new(big.Int).QuoRem(n, d, new(big.Int))
1259		switch r2 := new(big.Int).Lsh(r, 1); r2.Cmp(d) {
1260		case 1:
1261			q.Add(q, big.NewInt(1))
1262		case 0:
1263			if q.Bit(0) == 1 {
1264				q.Add(q, big.NewInt(1))
1265			}
1266		}
1267		return q
1268	}
1269	
1270	// String 让冲突原因中的序列身份可读且无歧义：name{k=v,...}，标签按键排序。
1271	// 名称、标签键、标签值是不含分隔字符（逗号、等号、花括号、引号、反斜杠）、
1272	// 不含首尾空白与不可打印字符的非空字符串时按原文呈现（cpu{host=a} 保持原样）；
1273	// 否则以带引号的字符串字面量呈现，使内容字符与标签边界永远可以区分——
1274	// 单标签值 "1,b=2" 渲染为 a="1,b=2"，与两标签 a=1,b=2 不再混淆；换行、
1275	// 制表符等呈现为 \n、\t 这样的可辨认文字标记，一条冲突原因始终是一条记录；
1276	// 空字符串值渲染为 ""，与无标签的 {} 明确区分。渲染只依赖解析后的真实身份，
1277	// 与标签书写顺序、字符是否以 JSON 转义书写无关。
1278	func (r SeriesRef) String() string {
1279		var b strings.Builder
1280		b.WriteString(identityText(r.Name))
1281		b.WriteByte('{')
1282		for i, p := range sortedPairs(r.Labels) {
1283			if i > 0 {
1284				b.WriteByte(',')
1285			}
1286			b.WriteString(identityText(p.Key))
1287			b.WriteByte('=')
1288			b.WriteString(identityText(p.Value))
1289		}
1290		b.WriteByte('}')
1291		return b.String()
1292	}
1293	
1294	// identityText 把身份组成部分（指标名、标签键、标签值）渲染为无歧义文本：
1295	// 不含分隔字符、首尾空白与不可打印字符的非空字符串原样返回；其余情况用
1296	// strconv.Quote 加引号并转义，引号边界标出内容的起止（首尾空格、空串可见），
1297	// 控制字符呈现为 \n、\t 等转义标记。分隔字符与引号、反斜杠一律被引号包裹，
1298	// 因此渲染结果不会把内容字符误读为标签边界。
1299	func identityText(s string) string {
1300		if s == "" || s != strings.TrimSpace(s) {
1301			return strconv.Quote(s)
1302		}
1303		for _, r := range s {
1304			if !unicode.IsPrint(r) || strings.ContainsRune(`,={}"\`, r) {
1305				return strconv.Quote(s)
1306			}
1307		}
1308		return s
1309	}
1310	
1311	// organizedSeries 是结果整理中的一条序列：携带已存序列指针、
1312	// 供结果直接使用的独立标签副本（标签书写顺序不影响身份，
1313	// 副本使调用方对结果的修改不能回写存储），以及该副本按键升序
1314	// 整理好的键值对，供排序比较直接复用。写入快照与区间查询都经由
1315	// organizeSeries 得到这样的条目，区别只在入选的序列范围。
1316	type organizedSeries struct {
1317		sr    *storedSeries
1318		ref   SeriesRef
1319		pairs []labelPair
1320	}
1321	
1322	// seriesLess 是写入快照与区间查询共用的序列次序约定：先按指标名字符串
1323	// 字典序，同名再按标签键升序后的键值对逐对比较（先比键再比值，前一对
1324	// 相同才比下一对；较短集合是完整前缀时排前，无标签序列因此排在最前）。
1325	// 标签值按字符串比较（"10" 在 "2" 之前）。排序只看解析后的真实身份，
1326	// 与冲突原因里的展示文字、标签的输入次序无关。
1327	func seriesLess(a, b organizedSeries) bool {
1328		if a.ref.Name != b.ref.Name {
1329			return a.ref.Name < b.ref.Name
1330		}
1331		return compareLabelPairs(a.pairs, b.pairs) < 0
1332	}
1333	
1334	// organizeSeries 是写入快照与三种查询成功结果共用的序列身份整理：对入选的每条已存序列
1335	// 复制独立的标签副本、预整理按键升序的键值对，并按 seriesLess 的统一次序
1336	// 排列。入选范围由调用方决定：写入快照传入全部已提交序列，三种区间查询只
1337	// 传入名称与标签条件命中的序列；它们因此遵循同一套整理规则而各自保留数据
1338	// 范围。每条序列的标签只在入选时整理一次：排序后的键值对随条目保留，sort
1339	// 的反复比较直接复用同一份结果，不会因一条序列参与多次比较而反复整理同一
1340	// 套标签。整理结果不复制采样点；写入快照的采样点选取与升序排列由
1341	// allSeriesPoints 完成，均值查询只在点表上计数与求和，采样明细查询由
1342	// seriesPointsInRange 按区间选取并升序排列，固定窗口查询直接在点表上按窗口
1343	// 下标归组、只围绕实际有点的窗口累计计数与精确求和。
1344	func organizeSeries(selected []*storedSeries) []organizedSeries {
1345		out := make([]organizedSeries, 0, len(selected))
1346		for _, sr := range selected {
1347			// 标签必须复制：成功结果是当次操作的独立记录，
1348			// 调用方修改结果标签不能改动已存序列的身份。
1349			labels := cloneLabels(sr.ref.Labels)
1350			out = append(out, organizedSeries{
1351				sr:    sr,
1352				ref:   SeriesRef{Name: sr.ref.Name, Labels: labels},
1353				pairs: sortedPairs(labels),
1354			})
1355		}
1356		sort.Slice(out, func(i, j int) bool { return seriesLess(out[i], out[j]) })
1357		return out
1358	}
1359	
1360	// allSeriesPoints 按 timestamp 升序返回一条已存序列的全部采样点，供写入快照
1361	// 展示。选取、升序排列与点构造与采样明细查询共用 seriesPoints，区别只在传入
1362	// 的选取范围是全部而不是闭区间。
1363	func allSeriesPoints(sr *storedSeries) []Point {
1364		return seriesPoints(sr, nil)
1365	}
1366	
1367	// seriesPoints 是写入快照与采样明细查询共用的采样点整理：从已存序列的点表中
1368	// 选出 keep 命中的时间戳（keep 为 nil 表示全部选取），按 timestamp 升序排列，
1369	// 每个时间戳配上点表中实际存储的 value（数值与时间戳一一对应，排序只动时间戳
1370	// 列表、不重配对值；int64 比较保留整数精度，float64 原样取出，负零保持负零）。
1371	// 返回的是新建切片与新建 Point，不持有点表的任何引用：调用方对结果的修改不
1372	// 影响存储，也不影响此前或此后取得的其他成功结果；取得结果后再写入新点，该份
1373	// 结果也不跟随存储变化。均值查询不构造这样的明细列表，只在点表上计数与求和。
1374	func seriesPoints(sr *storedSeries, keep func(ts int64) bool) []Point {
1375		tsList := make([]int64, 0, len(sr.points))
1376		for ts := range sr.points {
1377			if keep != nil && !keep(ts) {
1378				continue
1379			}
1380			tsList = append(tsList, ts)
1381		}
1382		sort.Slice(tsList, func(i, j int) bool { return tsList[i] < tsList[j] })
1383		points := make([]Point, len(tsList))
1384		for i, ts := range tsList {
1385			points[i] = Point{Timestamp: ts, Value: sr.points[ts]}
1386		}
1387		return points
1388	}
1389	
1390	// snapshot 生成按规范排序的全部序列视图：入选范围是全部已提交序列，
1391	// 身份整理与次序来自 organizeSeries，点排列来自 allSeriesPoints；
1392	// 三种区间查询共用同一套身份整理，各自只对命中序列统计均值、列出明细或
1393	// 按固定窗口统计。
1394	func (s *MetricStore) snapshot(added, duplicates int) *BatchResult {
1395		all := make([]*storedSeries, 0, len(s.series))
1396		for _, sr := range s.series {
1397			all = append(all, sr)
1398		}
1399		organized := organizeSeries(all)
1400		views := make([]SeriesView, 0, len(organized))
1401		for _, os := range organized {
1402			views = append(views, SeriesView{
1403				Name:   os.ref.Name,
1404				Labels: os.ref.Labels,
1405				Points: allSeriesPoints(os.sr),
1406			})
1407		}
1408		return &BatchResult{Status: "ok", Added: added, Duplicates: duplicates, Series: views}
1409	}
1410

