229			{`[{"name":"m","timestamp":1,"value":1},{"name":7}]`, 2},                 // 错误位置从 1 开始
230			{`[{"name":"m","timestamp":1,"value":1,"labels":{"a":"1","a":"2"}}]`, 1}, // 重复标签键
231		}
232		for _, tc := range cases {
233			store := NewMetricStore()
234			lerr := mustFail(t, store, tc.line)
235			if lerr.Index != tc.index {
236				t.Errorf("line %s: index = %d, want %d (error: %s)", tc.line, lerr.Index, tc.index, lerr.Error)
237			}
238			if lerr.Conflict != nil {
239				t.Errorf("line %s: validation error must not carry conflict", tc.line)
240			}
241			// 任何失败都不应写入数据。
242			if got := len(mustOK(t, store, `[]`).Series); got != 0 {
243				t.Errorf("line %s: store mutated by failed batch, series=%d", tc.line, got)
244			}
245		}
