package main

import (
	"bytes"
	"math"
	"strings"
	"testing"
)

// 端到端回归保障 value 在 float64 有限范围上界两侧的实际处理，
// 贯穿 ingest 的写入、重复判定、整批原子性与后续查询：
//
//   - 1.7976931348623157e308 与 1.7976931348623158e308 都成功保存为
//     最大有限 float64；同序列同时间戳先后提交、同批提交都算重复，
//     不同时间戳保留多个点，查询 count 与有限 average 正确。
